// frontend/src/components/Metrices/AutomationCreationTab.js
import React, { useEffect, useMemo, useState } from "react";
import "../../styles/roiTabs.css";
import "../../styles/RecordEntry.css";

// ==== [CHANGE] New: local CSS (scoped) for bordered, professional tables + vertical tabs
const styles = `
.metric-vertabs { display: flex; gap: 12px; }
.metric-vertabs .tablinks { display: flex; flex-direction: column; min-width: 220px; }
.metric-vertabs .tablinks button {
  background: #f7f7f7; border: 1px solid #ddd; padding: 10px 12px; text-align: left; cursor: pointer;
}
.metric-vertabs .tablinks button.active { background: #fff; border-right-color: #fff; font-weight: 600; }
.metric-vertabs .tabcontent {
  flex: 1; background: #fff; border: 1px solid #ddd; padding: 12px; border-radius: 4px;
}
.metric-table-wrap { overflow-x: auto; }
.metric-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.metric-table th, .metric-table td {
  border: 1px solid #cfd3d7;
  padding: 8px 10px;
  vertical-align: top;
  word-break: break-word;
  background: #fff;
}
.metric-table thead th {
  background: #f0f3f6;
  font-weight: 600;
}
.metric-toolbar { display:flex; gap:12px; align-items: end; margin-bottom: 10px; }
.input { width:100%; }
.download-row { display:flex; gap:8px; flex-wrap: wrap; }
`;

// Shared dropdown values (Section 2)
const FY_OPTIONS = [
  "All Years",
  "FY-2019",
  "FY-2020",
  "FY-2021",
  "FY-2022",
  "FY-2023",
  "FY-2024",
  "FY-2025",
  "FY-2026 (To-Date)",
];

const BREAKDOWN_OPTIONS = [
  "Breakdown by App Fmk & Portfolio",
  "Breakdown by Applications",
];

// ==== [CHANGE] Table renderer with per-cell keys (so each cell can later fetch its own SQL)
function BorderedTable({ headers, rows, sectionKey }) {
  if (!headers?.length && !rows?.length) return null;
  return (
    <div className="metric-table-wrap">
      <table className="metric-table">
        <thead>
          <tr>
            {(headers || []).map((h, i) => (
              <th key={i}>{h || ""}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {(rows || []).map((r, ri) => (
            <tr key={ri}>
              {(headers || []).map((colName, ci) => {
                const cellKey = `${sectionKey}|r${ri}|c${ci}|${(colName || "").trim()}`;
                return (
                  <td key={ci} data-cell-key={cellKey}>
                    {/* Placeholder: each cell will later fetch its own value using cellKey */}
                    {r?.[ci] ?? ""}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function AutomationCreationTab() {
  // ==== [CHANGE] New: vertical tab state
  const [vtab, setVtab] = useState("raw"); // raw | powerbi | download

  // Section 1: consolidated (sheet: Creation)
  const [consData, setConsData] = useState({ headers: [], rows: [] });
  const [consBusy, setConsBusy] = useState(false);
  const [consErr, setConsErr] = useState("");

  // Section 2: monthly breakdown (sheet: MonthlyCreation)
  const [fy, setFy] = useState("All Years");
  const [breakdown, setBreakdown] = useState(BREAKDOWN_OPTIONS[0]);
  const [monData, setMonData] = useState({ headers: [], rows: [] });
  const [monBusy, setMonBusy] = useState(false);
  const [monErr, setMonErr] = useState("");

  // Fetch Section 1 (sheet: Creation)
  useEffect(() => {
    const run = async () => {
      try {
        setConsBusy(true);
        setConsErr("");
        const res = await fetch(
          "http://localhost:5000/api/automationmetricsdatafetch?tab=creation&view=consolidated"
        );
        const j = await res.json();
        setConsData({
          headers: j?.headers || [],
          rows: j?.rows || [],
        });
      } catch (e) {
        setConsErr("Failed to load Consolidated View");
        console.error(e);
      } finally {
        setConsBusy(false);
      }
    };
    run();
  }, []);

  // Fetch Section 2 (sheet: MonthlyCreation)
  useEffect(() => {
    const run = async () => {
      try {
        setMonBusy(true);
        setMonErr("");
        const qs = new URLSearchParams({
          tab: "creation",
          view: "monthly",
          fy: fy || "",
          breakdown: breakdown || "",
        }).toString();
        const res = await fetch(
          "http://localhost:5000/api/automationmetricsdatafetch?" + qs
        );
        const j = await res.json();
        setMonData({
          headers: j?.headers || [],
          rows: j?.rows || [],
        });
      } catch (e) {
        setMonErr("Failed to load Monthly Breakdown");
        console.error(e);
      } finally {
        setMonBusy(false);
      }
    };
    run();
  }, [fy, breakdown]);

  // ==== [CHANGE] Download handler (backend to implement)
  const handleDownload = async () => {
    try {
      const qs = new URLSearchParams({
        tab: "creation",
        // server will produce:
        // - Sheet 1: Consolidated View (Creation)
        // - Separate sheets for each breakdown value under MonthlyCreation
      }).toString();

      // Expecting the backend to return application/vnd.openxmlformats-officedocument.spreadsheetml.sheet
      const resp = await fetch("http://localhost:5000/api/automationmetricsdownload?" + qs);
      const blob = await resp.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "Automation_Creation_Report.xlsx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("download error", e);
      alert("Download failed. Backend endpoint not implemented yet.");
    }
  };

  return (
    <div className="tab-wrap">
      {/* ==== [CHANGE] Inject scoped styles */}
      <style>{styles}</style>

      {/* ==== [CHANGE] Vertical Tabs Wrapper */}
      <div className="metric-vertabs">
        {/* Left: Vertical buttons (W3Schools pattern adapted) */}
        <div className="tablinks">
          <button
            className={vtab === "raw" ? "active" : ""}
            onClick={() => setVtab("raw")}
          >
            Raw Data
          </button>
          <button
            className={vtab === "powerbi" ? "active" : ""}
            onClick={() => setVtab("powerbi")}
          >
            Report (PowerBI)
          </button>
          <button
            className={vtab === "download" ? "active" : ""}
            onClick={() => setVtab("download")}
          >
            Download Reports
          </button>
        </div>

        {/* Right: Panel content */}
        <div className="tabcontent">
          {vtab === "raw" && (
            <>
              {/* Section 1 */}
              <div className="tab-section tab-section-yellow">Section 1: Consolidated View</div>
              {consBusy ? (
                <div className="text-gray-600" style={{ marginBottom: 12 }}>Loading…</div>
              ) : consErr ? (
                <div className="text-red-600" style={{ marginBottom: 12 }}>{consErr}</div>
              ) : (
                <BorderedTable
                  headers={consData.headers}
                  rows={consData.rows}
                  sectionKey="creation.section1"
                />
              )}

              {/* Section 2 */}
              <div className="tab-section tab-section-yellow" style={{ marginTop: 24 }}>
                Section 2: Monthly Breakdown
              </div>

              <div className="metric-toolbar">
                <div style={{ flex: 1 }}>
                  <label className="small-label">Select a year</label>
                  <select
                    className="input"
                    value={fy}
                    onChange={(e) => setFy(e.target.value)}
                  >
                    {FY_OPTIONS.map((o) => (
                      <option key={o} value={o}>{o}</option>
                    ))}
                  </select>
                </div>

                <div style={{ flex: 1 }}>
                  <label className="small-label">Select a Breakdown View</label>
                  <select
                    className="input"
                    value={breakdown}
                    onChange={(e) => setBreakdown(e.target.value)}
                  >
                    {BREAKDOWN_OPTIONS.map((o) => (
                      <option key={o} value={o}>{o}</option>
                    ))}
                  </select>
                </div>
              </div>

              {monBusy ? (
                <div className="text-gray-600">Loading…</div>
              ) : monErr ? (
                <div className="text-red-600">{monErr}</div>
              ) : (
                <BorderedTable
                  headers={monData.headers}
                  rows={monData.rows}
                  sectionKey={`creation.section2.${breakdown.replace(/\s+/g, "_")}`}
                />
              )}
            </>
          )}

          {vtab === "powerbi" && (
            <>
              <div className="tab-section tab-section-yellow">PowerBI Report</div>
              <div className="text-gray-600">
                Placeholder for embedded PowerBI report (iframe or powerbi-client React component).
              </div>
            </>
          )}

          {vtab === "download" && (
            <>
              <div className="tab-section tab-section-yellow">Download Reports</div>
              <div className="download-row">
                <button className="btn" onClick={handleDownload}>Download Excel</button>
              </div>
              <div className="text-gray-600" style={{ marginTop: 12 }}>
                The workbook will contain:
                <ul style={{ marginLeft: 18 }}>
                  <li>Consolidated View</li>
                  <li>
                    Separate sheets for Section 2 - Monthly Breakdown, one per
                    “Select a Breakdown View” option
                  </li>
                </ul>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
